import{_ as a,o as i,c as t,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Tech Talk: Persistent Bucket Notifications","description":"","frontmatter":{"title":"Ceph Tech Talk: Persistent Bucket Notifications","date":"2021-04-01T00:00:00.000Z","updated":"2021-04-02T00:00:00.000Z","tags":["Ceph","分布式存储","持久化桶通知","异步通知","两阶段提交"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Tech_Talk_-_Persistent_Bucket_Notifications.md","filePath":"posts/2021/Ceph_Tech_Talk_-_Persistent_Bucket_Notifications.md","lastUpdated":1780459816000}'),o={name:"posts/2021/Ceph_Tech_Talk_-_Persistent_Bucket_Notifications.md"};function s(r,e,h,n,c,p){return i(),t("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要-ceph-tech-talk-持久化桶通知功能介绍" tabindex="-1">会议纪要：Ceph Tech Talk - 持久化桶通知功能介绍 <a class="header-anchor" href="#会议纪要-ceph-tech-talk-持久化桶通知功能介绍" aria-label="Permalink to &quot;会议纪要：Ceph Tech Talk - 持久化桶通知功能介绍&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次Ceph技术讲座由Evolve主讲，主题为“持久化桶通知”（Persistent Bucket Notifications）。该功能将在即将发布的Pacific版本中推出，旨在提供一个额外的发布和订阅模型端点，增强系统的可靠性和灵活性。</p><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>持久化桶通知的概述</strong>：</p><ul><li>桶通知机制允许外部系统了解Ceph Redis网关上的操作，如对象的创建、删除和复制。</li><li>当前支持的端点包括HTTP、AMQP、RabbitMQ和Kafka，未来计划增加更多端点。</li></ul></li><li><p><strong>持久化桶通知的优势</strong>：</p><ul><li>异步通知机制：不等待回复，立即回复客户端，确保消息稍后到达端点。</li><li>两阶段提交队列：确保通知的可靠性和持久性，即使Redis网关崩溃也能恢复。</li><li>重试机制：确保消息最终到达端点，通过持久化队列实现。</li></ul></li><li><p><strong>实现细节</strong>：</p><ul><li>每个持久化主题关联一个队列，确保消息的顺序和避免重复。</li><li>使用对象锁机制确保只有一个Redis网关处理队列中的消息。</li><li>队列和锁的定期清理机制，防止积累和过期。</li></ul></li><li><p><strong>未来发展和改进</strong>：</p><ul><li>增加更多端点类型，如AWS Lambda和SNS。</li><li>改进调试工具，提供更直观的队列所有权信息。</li><li>考虑将超时配置变为可配置项，以适应不同集群规模的需求。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>持久化桶通知功能将在Pacific版本中发布，提供更可靠的异步通知机制。</li><li>未来将增加更多端点类型和改进工具，以增强用户体验和功能性。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续开发和完善持久化桶通知功能，包括增加新端点和改进调试工具。</li><li>考虑将超时配置变为可配置项，以适应不同用户需求。</li><li>鼓励社区参与和反馈，以推动功能的进一步发展和优化。</li></ul><h4 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h4><ul><li>Evolve的邮箱和IRC信息将在视频后续提供，以便社区成员联系和参与讨论。</li></ul><h4 id="其他信息" tabindex="-1">其他信息 <a class="header-anchor" href="#其他信息" aria-label="Permalink to &quot;其他信息&quot;">​</a></h4><ul><li>提醒参与者填写用户调查，以帮助Ceph团队了解用户需求和使用情况。</li></ul><p>本次讲座为Ceph社区成员提供了关于持久化桶通知功能的详细介绍和未来发展方向，旨在增强Ceph在分布式存储领域的竞争力和用户满意度。</p>',14)])])}const d=a(o,[["render",s]]);export{u as __pageData,d as default};
